INSERT INTO idee_outing (slug,title,summary,description,kind,status,place_id,environment,min_age,duration_minutes,is_demo,practical_info) VALUES
('balade-vignoble','Une balade au fil des vignes','Prendre les chemins du vignoble et profiter des paysages alsaciens.','Une idée de promenade entre villages et coteaux. Cet exemple illustre une sortie permanente, à organiser selon la météo et les conditions locales.','permanent','published',5,'outdoor',0,120,true,'Prévoir des chaussures de marche et de l’eau. Itinéraire à confirmer.'),
('marche-createurs','Le rendez-vous des créateurs','Flâner entre les stands et découvrir des créations artisanales.','Un marché fictif pour illustrer une récurrence : le premier samedi de chaque mois, de 10 h à 18 h.','event','published',1,'outdoor',0,null,true,'Exemple de calendrier mensuel ; aucun événement réel annoncé.'),
('weekend-patrimoine','Un week-end de découvertes','Trois jours pour explorer le patrimoine et les savoir-faire.','Un événement fictif réparti sur trois jours. Chaque journée possède ses horaires ; il n’est pas présenté comme ouvert pendant la nuit.','event','published',2,'mixed',0,null,true,'Programme de démonstration.'),
('atelier-famille','Un atelier à partager en famille','Créer, essayer et repartir avec une idée pleine de couleurs.','Un atelier fictif proposé le mercredi et le samedi après-midi. Cet exemple utilise une règle hebdomadaire et un tarif par participant.','event','published',4,'indoor',6,90,true,'Exemple uniquement : aucune réservation disponible.'),
('escapade-vosges','Une échappée au pied des Vosges','S’offrir une pause au vert sur les sentiers du piémont.','Une idée de sortie nature sans date imposée. Les conditions d’accès, l’itinéraire et la météo doivent être vérifiés avant de partir.','permanent','published',3,'outdoor',8,180,true,'Équipement adapté au terrain conseillé.'),
('concert-soiree','Une soirée en musique','Un moment musical pour prolonger la journée.','Un concert fictif en soirée pour illustrer un événement ponctuel avec heure de début et heure de fin.','event','published',6,'outdoor',0,120,true,'Date et programme fictifs.');
